mapper.select:
SELECT I.ID AS "id" ,I.TITLE AS "title" ,I.BODY AS "body" ,I.CATEGORY AS "category" ,I.STATUS AS "status" ,I.ADMIN_NOTE AS "adminNote" ,I.VOTE_COUNT AS "voteCount" ,U.NICKNAME AS "nickname" ,(I.USER_ID = #{userId}) AS "mine" ,EXISTS (SELECT 1 FROM T_IDEA_VOTE V WHERE V.IDEA_ID = I.ID AND V.USER_ID = #{userId}) AS "voted" ,(EXTRACT(EPOCH FROM I.INS_DAY) * 1000)::BIGINT AS "insAt" FROM T_IDEA I JOIN T_USER U ON U.ID = I.USER_ID WHERE 1=1 AND I.DEL_DAY IS NULL
AND I.STATUS = #{status}
ORDER BY I.ID DESC
ORDER BY CASE WHEN I.STATUS IN ('DONE', 'REJECTED') THEN 1 ELSE 0 END, I.VOTE_COUNT DESC, I.ID DESC
LIMIT #{limit}

mapper.update:
UPDATE T_IDEA
   SET DEL_DAY = NOW()
 WHERE 1=1
   AND ID      = #{id}
   AND USER_ID = #{userId}
   AND DEL_DAY IS NULL

mapper.delete:
DELETE FROM T_IDEA_VOTE
 WHERE 1=1
   AND IDEA_ID = #{ideaId}
   AND USER_ID = #{userId}

mapper.update:
UPDATE T_IDEA
   SET VOTE_COUNT = GREATEST(0, VOTE_COUNT + #{delta})
 WHERE ID = #{ideaId}

UPDATE T_IDEA
   SET STATUS     = #{status}
      ,ADMIN_NOTE = #{note}
      ,UPD_DAY    = NOW()
 WHERE 1=1
   AND ID = #{id}
   AND DEL_DAY IS NULL
